param([switch]$Check)

$ErrorActionPreference = 'Stop'
$workflow = Join-Path $PSScriptRoot '..' '.github' 'workflows' 'build-target.yml'
$runners = '{"linux-x64":"ubuntu-24.04","linux-arm64":"ubuntu-24.04","windows-x64":"windows-2025","windows-arm64":"windows-2025","macos-x64":"macos-26","macos-arm64":"macos-26"}'
$lines = [System.Collections.Generic.List[string]]::new()
$lines.AddRange([string[]]@(
    '# Generated by scripts/stages.ps1; edit that script and regenerate.',
    'name: Build target',
    'on:',
    '  workflow_call:',
    '    inputs:',
    '      target:',
    '        type: string',
    '        required: true',
    '      stage-minutes:',
    '        type: string',
    '        default: "280"',
    '      resume-run:',
    '        type: string',
    '        default: ""',
    'permissions:',
    '  contents: read',
    '  actions: read',
    'jobs:'
))
foreach ($stage in 1..16) {
    $lines.Add("  s${stage}:")
    $lines.Add("    name: stage $stage")
    if ($stage -gt 1) {
        $previous = $stage - 1
        $lines.Add("    needs: s$previous")
        $lines.Add("    if: `${{ !cancelled() && needs.s$previous.outputs.complete == 'false' }}")
    } else {
        $previous = ''
    }
    $lines.AddRange([string[]]@(
        "    runs-on: `${{ fromJSON('$runners')[inputs.target] }}",
        '    timeout-minutes: 355',
        '    outputs:',
        '      complete: ${{ steps.stage.outputs.complete }}',
        '    steps:',
        '      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6',
        '      - id: stage',
        '        uses: ./.github/actions/stage',
        '        with:',
        '          target: ${{ inputs.target }}',
        "          stage: `"$stage`"",
        "          previous: `"$previous`"",
        '          budget-minutes: ${{ inputs.stage-minutes }}'
    ))
    if ($stage -eq 1) {
        $lines.Add('          resume-run: ${{ inputs.resume-run }}')
    }
}
$needs = (1..16 | ForEach-Object { "s$_" }) -join ', '
$lines.AddRange([string[]]@(
    '  verdict:',
    "    needs: [$needs]",
    '    if: ${{ always() }}',
    '    runs-on: ubuntu-latest',
    '    steps:',
    '      - name: Require a finished build',
    '        env:',
    '          NEEDS: ${{ toJSON(needs) }}',
    '        run: |',
    '          echo "$NEEDS" | jq -e ''[.[] | select(.result == "success" and .outputs.complete == "true")] | length == 1'''
))
$content = ($lines -join "`n") + "`n"
if ($Check) {
    if ([System.IO.File]::ReadAllText($workflow) -cne $content) {
        throw 'Generated workflow differs; run pwsh scripts/stages.ps1.'
    }
} else {
    [System.IO.File]::WriteAllText($workflow, $content, [System.Text.UTF8Encoding]::new($false))
}
